import{_ as t,o as r,c as e,a2 as o}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"黑暗时代","description":"","frontmatter":{},"headers":[],"relativePath":"表层/历史/黑暗时代.md","filePath":"表层/历史/黑暗时代.md","lastUpdated":1787065118000}'),l={name:"表层/历史/黑暗时代.md"};function i(n,a,h,s,u,d){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="黑暗时代" tabindex="-1">黑暗时代 <a class="header-anchor" href="#黑暗时代" aria-label="Permalink to &quot;黑暗时代&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>黑暗时代指共同体解体后约200年的至暗时期。新五族以魔法与奴隶制统治大陆，文明倒退、生灵涂炭，直至约黑暗时代200年，新五族统治彻底消失，黑暗时代宣告结束。</p><h2 id="共同体的解体与新五族" tabindex="-1">共同体的解体与新五族 <a class="header-anchor" href="#共同体的解体与新五族" aria-label="Permalink to &quot;共同体的解体与新五族&quot;">​</a></h2><h3 id="共同体解体" tabindex="-1">共同体解体 <a class="header-anchor" href="#共同体解体" aria-label="Permalink to &quot;共同体解体&quot;">​</a></h3><p>约建国200年，共同体在鹰族代表的宣布下正式解体，分裂为数个法师封地。</p><h3 id="新五族统治" tabindex="-1">新五族统治 <a class="header-anchor" href="#新五族统治" aria-label="Permalink to &quot;新五族统治&quot;">​</a></h3><p>猪族、蝠族、豹族、虎族与鹰族合并组成新五族，成为黑暗时代的统治者。其中：</p><ul><li><strong>鹰族</strong>：搭建了黑暗时代的整个框架——&quot;强者为尊、贵族世袭&quot;等规则均由鹰族定下</li><li><strong>其余四族</strong>：为讨好鹰族、换取地位，逐渐细化出各种压迫手段（如摧毁教育体系、使用与圈养奴隶等）</li></ul><p>新五族是第一批系统掌握魔法的种族。在鹰族带领下，新五族将魔法作为巩固统治、压制普通生灵的核心手段。</p><h2 id="奴隶制的形成" tabindex="-1">奴隶制的形成 <a class="header-anchor" href="#奴隶制的形成" aria-label="Permalink to &quot;奴隶制的形成&quot;">​</a></h2><p>奴隶制在黑暗时代渐渐形成，各族的处境各不相同：</p><ul><li><strong>牛族</strong>：第一个彻底沦为奴隶的种族</li><li><strong>狼族</strong>：因天性纯善、易于驯化，被其余种族大肆建立&quot;狼圈&quot;专门繁育，作为奴隶来源被大规模繁育</li><li><strong>狐族</strong>：全族皆为雌性、后代亦只会是雌性狐族，天生成为性服务奴隶的人选</li><li><strong>鹿族</strong>：逐渐成为新五族法师的助手与宠物</li></ul><p>黑暗时代顶峰（约100年时），统治阶层完全不用劳作，一出生便有无数下人伺候，用奴隶性命取乐之事不断上演，特殊服务业奴隶的损耗比矿场劳工还高。</p><h2 id="魔法与法师" tabindex="-1">魔法与法师 <a class="header-anchor" href="#魔法与法师" aria-label="Permalink to &quot;魔法与法师&quot;">​</a></h2><h3 id="觉醒与筛查" tabindex="-1">觉醒与筛查 <a class="header-anchor" href="#觉醒与筛查" aria-label="Permalink to &quot;觉醒与筛查&quot;">​</a></h3><p>地脉灾难后，魔法天赋的觉醒一般发生在<strong>4至8岁</strong>之间。上层系统性筛查这一年龄段的奴隶，发现天赋者即刻处死。</p><p>奴隶们学会隐藏天赋，但因魔法带来的身体虚弱无法掩饰，最终仍会被发现。部分魔法奴隶在临死前暴动，能伤及甚至杀死奴隶官。</p><h3 id="法师的处境" tabindex="-1">法师的处境 <a class="header-anchor" href="#法师的处境" aria-label="Permalink to &quot;法师的处境&quot;">​</a></h3><p>法师大多体弱多病、深居简出，其根源不为外人所知。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></blockquote><h2 id="贱民与粮食危机" tabindex="-1">贱民与粮食危机 <a class="header-anchor" href="#贱民与粮食危机" aria-label="Permalink to &quot;贱民与粮食危机&quot;">​</a></h2><h3 id="贱民阶级" tabindex="-1">贱民阶级 <a class="header-anchor" href="#贱民阶级" aria-label="Permalink to &quot;贱民阶级&quot;">​</a></h3><p>黑暗时代的社会并非简单的&quot;法师与奴隶&quot;二元结构，在两者之间，存在着人数最多的<strong>贱民阶级</strong>：</p><ul><li><strong>定义</strong>：未被奴役但也无人身权利的平民。名义上是&quot;自由身&quot;，实际上被束缚在土地、矿场或特定区域，靠出卖劳动力换取微薄的生存资料</li><li><strong>生存状态</strong>：自行解决食宿，但需向法师缴纳高额赋税——养奴隶需要成本，压榨贱民则几乎不需要</li><li><strong>贱民区生态</strong>：通常位于法师城邦边缘、废弃的共同体遗址周边或山林边缘的贫瘠土地。这里没有法律与秩序，偷窃、告密与零星的善意并存</li></ul><h3 id="粮食连年减产" tabindex="-1">粮食连年减产 <a class="header-anchor" href="#粮食连年减产" aria-label="Permalink to &quot;粮食连年减产&quot;">​</a></h3><p>地脉灾难后，全境粮食持续减产。减产不是突然的大饥荒，而是一种缓慢的窒息感——每年比前一年少一点，碗里的粥越来越稀，饿死的老人越来越多。减产主要作用于贱民与奴隶身上。</p><h3 id="捕奴队" tabindex="-1">捕奴队 <a class="header-anchor" href="#捕奴队" aria-label="Permalink to &quot;捕奴队&quot;">​</a></h3><p>随着贱民群体在萎缩（饿死的、逃亡的），供需失衡之下，法师们开始更频繁地组织<strong>捕奴队</strong>——专门搜捕逃亡奴隶、抓走贱民充奴的武装队伍。</p><h2 id="旧科技的废弃" tabindex="-1">旧科技的废弃 <a class="header-anchor" href="#旧科技的废弃" aria-label="Permalink to &quot;旧科技的废弃&quot;">​</a></h2><p>共同体时期的科技并未被盲目摧毁，而是主要因<strong>无人维护与知识断层</strong>而自然废弃。值得注意的是，新五族的贵族高层中仍有不少人继续维护、使用旧时代的科技产物（如电灯）。同时，部分法师脱离体制，在偏远地区自立城邦，统治普通生灵。</p><h2 id="兔族的避难村落-约120年" tabindex="-1">兔族的避难村落（约120年） <a class="header-anchor" href="#兔族的避难村落-约120年" aria-label="Permalink to &quot;兔族的避难村落（约120年）&quot;">​</a></h2><p>约黑暗时代120年，兔族在南方深山密林中建立起收留逃亡者的村落。狼村、狐村等村落初步建立于此，成为黑暗时代中为数不多的庇护之所。</p><h2 id="狼族少年与-狼灾时期-约180年" tabindex="-1">狼族少年与&quot;狼灾时期&quot;（约180年） <a class="header-anchor" href="#狼族少年与-狼灾时期-约180年" aria-label="Permalink to &quot;狼族少年与&quot;狼灾时期&quot;（约180年）&quot;">​</a></h2><p>约黑暗时代180年，一位被南方狼村收养的狼族孤儿被猪族奴隶官抓走，亲友在其面前惨死。仇恨点燃了其体内的力量，少年屠戮奴隶厂、解放狼族，建立初步国家。</p><p>少年曾与新五族签订和平条例，试图和平共处，却遭猪、虎、豹、蝠四族联合背刺，狼族死伤惨重。此后，少年独自一人巡游大地四方，数年内灭绝猪、虎、豹、蝠四族，并在即将灭绝鹰族时突然消失。</p><p>此阶段被其余种族称为**&quot;狼灾时期&quot;**。民间对少年力量的称呼不一，有&quot;狼魔法&quot;&quot;邪法&quot;&quot;复仇之力&quot;等说法，也有直接将其归为&quot;魔法&quot;的。</p><h2 id="黑暗时代的终结" tabindex="-1">黑暗时代的终结 <a class="header-anchor" href="#黑暗时代的终结" aria-label="Permalink to &quot;黑暗时代的终结&quot;">​</a></h2><p>黑暗时代后期，鹿族暗中积蓄力量，最终走向台面（其具体手段并无公开记载）。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><p>狐族在狼族庇佑下建立城邦，其余种族亦逐渐走向独立。约黑暗时代200年，新五族的统治彻底消失，黑暗时代结束。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></li><li><p><a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></li><li><p><a href="./../../中层/人物/狼族少年" class="layer-link" data-layer="中层">狼族少年</a></p></li><li><p><a href="./共同体时期">共同体时期</a></p></li><li><p><a href="./当前时代">当前时代</a></p></li></ul><hr>',45)])])}const c=t(l,[["render",i]]);export{q as __pageData,c as default};
